// g_hybridMutex is defined in aatped.cpp (shared with hybrid learning hot path)
extern std::mutex g_hybridMutex;

// C-011: g_autoProfileMutex protects g_autoProfileMode (string cannot be atomic).
std::mutex g_autoProfileMutex;

// ROUND-007: user's persistent control-mode choice (active/assist/passive).
// Distinct from g_cfg.controlMode which is the EFFECTIVE mode (can be overridden
// by safety/latch conditions like crash-loop or thermal emergency). When safety
// clears, g_cfg.controlMode is restored to this value.
std::mutex g_userControlModeMutex;
std::string g_userControlMode = "assist";

std::string getUserControlMode() {
    std::lock_guard<std::mutex> lk(g_userControlModeMutex);
    return g_userControlMode;
}
void setUserControlMode(const std::string& m) {
    std::lock_guard<std::mutex> lk(g_userControlModeMutex);
    g_userControlMode = m;
}

// ROUND-007: called by safemode CRASH_LOOP self-heal to restore the user's
// persistent mode after the safety override has aged out.
void restoreUserControlMode() {
    std::string userMode = getUserControlMode();
    {
        std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
        g_cfg.controlMode = userMode;
    }
    atomicWriteFile((std::string(STATE_DIR) + "/control_mode").c_str(), userMode);
    atomicWriteFile((std::string(STATE_DIR) + "/control_mode_reason").c_str(),
                    std::string("restored_after_crash_window"));
    LOG_INFO("ROUND-007: control mode restored to user choice: %s", userMode.c_str());
}

void signalHandler(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        g_shouldExit.store(1, std::memory_order_relaxed);
    } else if (sig == SIGUSR1) {
        g_reloadProfile.store(1, std::memory_order_relaxed);
    }
}

// P1-19: Crash signal handler (real original aatped.cpp:4189-4220)
// Catches fatal signals and writes crash_signal state file before re-raising.
// This gives the watchdog and CLI visibility into crashes instead of silent death.
static void crashSignalHandler(int sig) {
    const char* sigName = "UNKNOWN";
    switch (sig) {
        case SIGSEGV: sigName = "SIGSEGV"; break;
        case SIGABRT: sigName = "SIGABRT"; break;
        case SIGFPE:  sigName = "SIGFPE";  break;
        case SIGILL:  sigName = "SIGILL";  break;
        case SIGBUS:  sigName = "SIGBUS";  break;
    }
    // Write crash signal state file.
    // P1-2 fix: the old code built the path via std::string(STATE_DIR)+... which
    // calls malloc() — NOT async-signal-safe (can deadlock the heap lock in a
    // crash context). STATE_DIR is a runtime const char*, so we build the path in
    // a small stack buffer with a bounded manual copy (no heap, no locking, no
    // non-safe libc calls). open()/write()/close() are async-signal-safe.
    // P3-25: buffer enlarged from 96 to 160 bytes. STATE_DIR is a short
    // /dev node path, but the bounded copy below already truncates safely; the
    // larger headroom avoids clipping a non-default STATE_DIR that would have
    // silently produced a mangled (and thus uninformative) crash_signal path.
    char pathBuf[160];
    int pi = 0;
    for (; STATE_DIR[pi] != '\0' && pi < (int)sizeof(pathBuf) - 1; pi++)
        pathBuf[pi] = STATE_DIR[pi];
    const char* suffix = "/crash_signal";
    for (int si = 0; suffix[si] != '\0' && pi < (int)sizeof(pathBuf) - 1; si++, pi++)
        pathBuf[pi] = suffix[si];
    pathBuf[pi] = '\0';
    // P1-8: crash_signal state file must be 0600 (root-only), not 0644.
    // v6.0.0 S-02: O_NOFOLLOW refuses to follow a trailing symlink (matches the
    // canonical writeFile() in aatped_utils.cpp:460) — a malicious planted symlink
    // at STATE_DIR/crash_signal cannot redirect this crash write into an
    // attacker-watched file. O_CLOEXEC already present.
    int fd = open(pathBuf, O_WRONLY | O_CREAT | O_TRUNC | O_NOFOLLOW | O_CLOEXEC, 0600);
    if (fd >= 0) {
        const char* msg = sigName;
        size_t len = 0;
        while (msg[len]) len++;
        ssize_t w = write(fd, msg, len);
        (void)w;
        close(fd);
    }
    // Re-raise with default handler to produce core dump / proper exit
    signal(sig, SIG_DFL);
    raise(sig);
}

void installCrashHandlers() {
    // P2: lock down the file-creation mask BEFORE any daemon-side file/dir is
    // created. Without this the process inherits the launcher's umask (often
    // 022), so mode 0600 opens still land world-readable on files that are
    // created before the explicit fchmod() calls run. 0077 -> owner-only for
    // everything we create; callers that need looser modes must chmod explicitly.
    umask(0077);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = crashSignalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGSEGV, &sa, nullptr);
    sigaction(SIGABRT, &sa, nullptr);
    sigaction(SIGFPE,  &sa, nullptr);
    sigaction(SIGILL,  &sa, nullptr);
    sigaction(SIGBUS,  &sa, nullptr);
}

// ============================================================================
// CONTROL COMMAND PROCESSING
// ============================================================================
// P3-1: Safe integer parsing helper — atoi("abc") returns 0 silently,
// so we pre-check that the string is all digits before calling atoi.
// P2-13: also bound the length so a huge digit string ("99999999999999...")
// cannot overflow parseIntSafe/atoi. 10 digits covers every positive 32-bit
// value (max 4294967295 = 10 digits); longer inputs are rejected.
static bool isAllDigits(const char* s) {
    if (!s || !*s) return false;
    size_t slen = 0;
    for (const char* p = s; *p; ++p) {
        if (*p < '0' || *p > '9') return false;
        slen++;
    }
    if (slen > 10) return false;
    return true;
}

// P1-1: control-line character whitelist, shared by the root control pipe reader
// (processControlCommands) AND the on-disk command queue drain
// (aatpe_command_queue.cpp::commandQueueDrain). Only [a-z0-9_=.-&] allowed, max 256
// bytes. Extracting it here so the queue drain — which reads command bytes off
// disk — applies the SAME injection gate instead of trusting the file contents.
bool isValidControlChars(const std::string& line) {
    if (line.empty() || line.size() > 256) return false;
    for (char c : line) {
        // R6-009: also allow uppercase A-F — the HMAC signature after ".sig=" is
        // hex and some producers emit uppercase hex, which the old [a-z] gate
        // rejected outright (the whole command dropped). Other uppercase letters
        // are still rejected.
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'F') || (c >= '0' && c <= '9') ||
              c == '_' || c == '=' || c == '.' || c == '-' || c == '&')) {
            return false;
        }
    }
    return true;
}

// R6-003/R6-004/R6-005: parse an all-digits string into a non-negative int and
// REJECT overflow rather than collapsing it to 0. The command handlers pre-filter
// with isAllDigits() (digits only, <=10 chars), but a 10-digit value like
// "9999999999" overflows int; the old parseIntSafe() returned def=0, and 0 is a
// legitimate value for these commands (log_level=0 / autoProfile=0 / thermal=false),
// so the overflow was silently accepted as the very value it should have rejected.
// Returns false on overflow / non-digit / out-of-int-range; on success `out` holds
// the parsed value (>=0).
static bool parseNonNegChecked(const char* s, int& out) {
    if (!s || !*s) return false;
    errno = 0;
    char* end = nullptr;
    long long v = strtoll(s, &end, 10);
    if (end == s || *end != '\0' || errno == ERANGE) return false;
    if (v < 0 || v > INT_MAX) return false;
    out = (int)v;
    return true;
}

// [split] config functions moved to aatped_config.cpp


void processControlCommands() {
    // HTTP /control endpoint writes to control_cmd, but we historically
    // only read /control. Merge control_cmd into /control so WebUI buttons work.
    // P2-14 : atomic-rename handoff. Previously we opened
    // control_cmd, read it, then unlinked it. If a second producer wrote a new
    // command into control_cmd between our read and our unlink, the unlink
    // deleted that NEW command (lost command / mailbox overwrite). We now rename
    // control_cmd to a per-process staging name FIRST (atomic: rename either
    // succeeds and we own the bytes, or it fails because no mailbox existed),
    // then read+unlink the staging copy. A producer that writes a new control_cmd
    // after our rename creates a fresh file picked up on the next loop.
    {
        std::string cmdPath = std::string(RUN_DIR) + "/control_cmd";
        std::string staging = cmdPath + ".processing";
        if (::rename(cmdPath.c_str(), staging.c_str()) == 0) {
            // R6-008: bound the read size. The control_cmd mailbox is root-owned
            // but we still must not read an unbounded file into memory; 64KB is
            // far larger than any real single command.
            constexpr std::streamoff kMaxControlCmd = std::streamoff(64) * 1024;
            std::string content;
            bool oversized = false;
            std::streamoff fileSize = 0;
            {
                std::ifstream cf(staging);
                if (cf) {
                    cf.seekg(0, std::ios::end);
                    fileSize = cf.tellg();
                    if (fileSize > kMaxControlCmd) {
                        oversized = true;
                    } else {
                        cf.seekg(0, std::ios::beg);
                        content.assign(std::istreambuf_iterator<char>(cf),
                                       std::istreambuf_iterator<char>());
                    }
                }
            }
            if (oversized) {
                LOG_WARN("CONTROL: control_cmd oversized (%lld bytes > 64KB), discarding",
                         (long long)fileSize);
                ::unlink(staging.c_str());
            } else if (!content.empty()) {
                std::ofstream out(std::string(RUN_DIR) + "/control", std::ios::app);
                if (out) {
                    out << content;
                    if (content.back() != '\n') out << '\n';
                    out.close();
                    ::unlink(staging.c_str());
                } else {
                    // R6-007: failed to merge into /control — do NOT silently drop
                    // the command. Return staging to control_cmd so the next loop
                    // retries instead of losing it.
                    LOG_WARN("CONTROL: cannot append to /control (%s); requeueing control_cmd",
                             aatpeErrStr(errno));
                    ::rename(staging.c_str(), cmdPath.c_str());
                }
            } else {
                ::unlink(staging.c_str());
            }
        }
    }
    // P1-2: atomic-rename handoff for the /control mailbox (same pattern already
    // used for control_cmd above). Previously we opened /control with ifstream,
    // dispatched every line (slow for set_* commands), and only THEN truncated
    // it. A producer that wrote a new command between the last getline() and the
    // truncate had that command wiped — a lost command. We now rename the
    // mailbox to a private .processing staging file FIRST; the rename atomically
    // gives us ownership of the bytes. Any command a producer writes AFTER the
    // rename lands on a brand-new /control inode and survives to the next loop,
    // instead of being truncated. We read+dispatch the staging copy, then unlink
    // it. We deliberately do NOT truncate /control here.
    std::string ctrlPath = std::string(RUN_DIR) + "/control";
    std::string ctrlStaging = ctrlPath + ".processing";
    if (::rename(ctrlPath.c_str(), ctrlStaging.c_str()) != 0) {
        // No mailbox (ENOENT) or rename race — nothing to drain this cycle.
        (void)aatpe_cmdq::commandQueueDrain();
        return;
    }
    std::ifstream f(ctrlStaging);
    if (!f) {
        ::unlink(ctrlStaging.c_str());
        (void)aatpe_cmdq::commandQueueDrain();
        return;
    }
    std::string line;
    while (std::getline(f, line)) {
        trim(line);
        if (line.empty()) continue;
        // P0-3.2: Strict input validation for APK control commands
        // Length limit: reject commands > 256 bytes (prevents buffer overflow and abuse)
        if (line.size() > 256) {
            LOG_WARN("CONTROL: rejected (length=%zu > 256)", line.size());
            continue;
        }
        // Character whitelist: only allow [a-z0-9_=.-&] (prevents injection and malformed input)
        // P1-1: shared gate (also used by the on-disk command queue drain).
        if (!isValidControlChars(line)) {
            LOG_WARN("CONTROL: rejected (invalid characters, only [a-z0-9_=.-&] allowed)");
            continue;
        }
        // Parameter count limit: at most 3 '=' separators (key=value format)
        int eqCount = 0;
        for (char c : line) if (c == '=') eqCount++;
        if (eqCount > 3) {
            LOG_WARN("CONTROL: rejected (too many '=' separators: %d > 3)", eqCount);
            continue;
        }
        // P1-2 / P23: HMAC signature verification for control commands.
        // Format: <command>.sig=<hex_sha256_hmac>
        //
        // SECURITY MODEL (P23): HMAC authentication is enforced at the HTTP boundary
        // in webui_http.cpp handleControl() (the network-facing, non-root-reachable
        // surface). This daemon-side reader consumes the root-owned control pipe
        // /dev/aatpe/control which is mode 0600 root — only root (aatpe-cli, KSU exec,
        // and the already-HMAC-verified HTTP path, which writes actualCmd here after
        // stripping .ts/.sig) can write it. Therefore unsigned commands arriving via
        // this root pipe are trusted by filesystem permission and are NOT rejected.
        // If a signature IS present we still verify it (defense in depth).
        {
            std::string actualCmd = line;
            bool hasSig = false;
            std::string sig;
            size_t sigPos = line.rfind(".sig=");
            if (sigPos != std::string::npos && sigPos > 0) {
                hasSig = true;
                sig = line.substr(sigPos + 5);
                actualCmd = line.substr(0, sigPos);
            }
            if (hasSig) {
                if (!verifyCommandHmac(actualCmd.c_str(), sig.c_str())) {
                    LOG_WARN("CONTROL: HMAC verification FAILED for '%s' (sig len=%zu)",
                             actualCmd.c_str(), sig.size());
                    continue;
                }
                line = actualCmd;  // strip signature before dispatch
            }
            // No rejection of unsigned commands here: see SECURITY MODEL above.
        }
        LOG_INFO("CONTROL: '%s'", line.c_str());
aatpe::CommandDispatcher::instance().dispatch(line, aatpe::DispatchAuth::ROOT);
    }
    f.close();
    // Remove our private snapshot. We do NOT truncate /control: any command a
    // producer wrote during the slow dispatch above now lives on a fresh /control
    // inode (created after our rename) and must survive to the next loop.
    ::unlink(ctrlStaging.c_str());

    // drain the real command queue directory
    // (/dev/aatpe/commands/). WebUI POST /control now enqueues here and returns a
    // command_id; the daemon executes each queued command in FIFO order and records
    // the result so GET /api/command/<id> can report it. The legacy control pipe
    // above remains fully supported (backward compatible).
    (void)aatpe_cmdq::commandQueueDrain();
}


// ----------------------------------------------------------------------------
// P1-1: Unified daemon control-mode entry point.
//
// Before this fix, the watchdog wrote directly to STATE_DIR/control_mode, but
// g_cfg.controlMode (which placement.cpp actually checks) was never updated.
// This function is the SINGLE choke point for every control-mode change:
// it updates g_cfg.controlMode under g_cfgMutex, drives the SystemState machine,
// writes STATE_DIR/control_mode atomically, and records the reason.
//
// Mode → SystemState mapping:
//   "active"   -> NORMAL, clear watchdog passive lock (full scheduling)
//   "assist"   -> NORMAL, clear watchdog passive lock (normal assist mode)
//   "passive"  -> PASSIVE, set watchdog passive lock (block migrations)
//   "emergency"-> EMERGENCY, set watchdog passive lock (thermal safety)
// ----------------------------------------------------------------------------
bool setRuntimeControlMode(const std::string& mode, const std::string& reason) {
    // Validate mode
    SystemState targetState;
    bool enterSafeLock;
    if (mode == "active") {
        targetState = SystemState::NORMAL;
        enterSafeLock = false;
    } else if (mode == "assist") {
        targetState = SystemState::NORMAL;
        enterSafeLock = false;
    } else if (mode == "passive") {
        targetState = SystemState::PASSIVE;
        enterSafeLock = true;
    } else if (mode == "emergency") {
        targetState = SystemState::EMERGENCY;
        enterSafeLock = true;
    } else {
        LOG_WARN("setRuntimeControlMode: invalid mode '%s' (must be active/assist/passive/emergency)",
                 mode.c_str());
        return false;
    }

    // ROUND-007c (v6.0.0 rel16): respect the user's manual mode lock on the
    // watchdog/safety path. The watchdog issues set_control_mode=passive on its
    // 3s tick (watchdog::kDefaultIntervalSec=3) for mig-rate / load / memory /
    // crash-loop latching. Before this fix that unconditionally overwrote the
    // user's explicitly-chosen "active": it set g_cfg.controlMode="passive",
    // latched g_watchdogPassiveLocked, drove system_state->PASSIVE and rewrote
    // STATE_DIR/control_mode — so the WebUI mode button bounced from 激进 back to
    // 被动 within ~3s on a healthy 40C device. g_userModeLock is set true by the
    // WebUI set_mode=active/assist path and cleared by set_mode=passive. When the
    // user has manually locked a faster mode, a NON-emergency safety downgrade to
    // passive must NOT clobber that choice. Real thermal emergency still overrides
    // (the one safety event that must always win), and a user who picks passive
    // clears the lock, so the safety path keeps working for them.
    bool isEmergency = (mode == "emergency");
    if (!isEmergency &&
        targetState == SystemState::PASSIVE &&
        g_userModeLock.load(std::memory_order_relaxed)) {
        LOG_WARN("[P1-1] control_mode safety downgrade '%s' (%s) IGNORED: user manually locked mode (active/assist); thermal emergency still overrides",
                 mode.c_str(), reason.c_str());
        atomicWriteFile((std::string(STATE_DIR) + "/control_mode_reason").c_str(),
                        std::string("ignored_user_lock:") + (reason.empty() ? "unknown" : reason));
        return false;
    }

    // 1. Update g_cfg.controlMode (EFFECTIVE mode) under g_cfgMutex.
    // ROUND-007: this is the WATCHDOG/SAFETY path — it must NOT overwrite
    // g_userControlMode (the user's persistent choice). When safety clears,
    // maybeRecover restores g_cfg.controlMode to g_userControlMode.
    {
        std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
        g_cfg.controlMode = mode;
    }

    // 2. Set/clear the watchdog passive lock BEFORE transitionToState, so the
    //    state machine enforces it. Entering safe mode locks it; recovery clears.
    g_watchdogPassiveLocked.store(enterSafeLock, std::memory_order_relaxed);

    // 3. Drive the unified SystemState machine. The transition may be deferred
    //    by the dwell debounce; that is fine — g_cfg.controlMode and the state
    //    file are already updated, and placement gates on g_cfg.controlMode.
    transitionToState(targetState, reason.c_str());

    // 4. Write STATE_DIR/control_mode atomically (snapshot under lock).
    std::string modeForFile;
    {
        std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
        modeForFile = g_cfg.controlMode;
    }
    atomicWriteFile((std::string(STATE_DIR) + "/control_mode").c_str(), modeForFile);
    // ROUND-007: do NOT persist CONTROL_MODE to aatpe.conf from the safety path.
    // That would overwrite the user's choice and survive restart. The user's
    // choice is persisted only via the user set_mode= path.
    // persistConfigKeyValue("CONTROL_MODE", modeForFile.c_str());  // safety: skip

    // 5. Record the reason for WebUI/diagnostics.
    atomicWriteFile((std::string(STATE_DIR) + "/control_mode_reason").c_str(),
                    reason.empty() ? std::string("unknown") : reason);

    LOG_WARN("[P1-1] control_mode -> %s (reason=%s, watchdog_lock=%d, state=%s)",
             mode.c_str(), reason.c_str(),
             enterSafeLock ? 1 : 0,
             systemStateToString(getSystemState()));
    return true;
}


// ----------------------------------------------------------------------------
// Executes one already-validated, already-HMAC-checked control line. This is the
// concrete executor behind aatpe::CommandDispatcher (parse->auth->validate->dispatch
// ->execute->audit). It used to be inlined in processControlCommands(); it is now a
// named primitive so the dispatcher choke point is real, not a placeholder.
// ----------------------------------------------------------------------------
ControlResult executeControlLine(const std::string& line) {
        ControlResult res;
        if (line.rfind("set_mode=", 0) == 0) {
            res.success = true;
            std::string mode = line.substr(9);
            trim(mode);
            // P3-6: validate set_mode value
            // Phase3 Batch1: drive unified state machine instead of direct controlMode write
            if (mode == "powersave" || mode == "passive") {
                // user explicitly chose battery-saver. Release the
                // manual-NORMAL guard so the load-based auto-degrade logic may
                // engage again.
                g_userModeLock.store(false, std::memory_order_relaxed);
                transitionToState(SystemState::PASSIVE, "user_set_mode_passive");
            } else if (mode == "assist" || mode == "active" || mode == "normal") {
                // user manually picked "正常" (NORMAL). Requirement:
                // the user MUST always be able to get back to NORMAL, no matter
                // what state the watchdog / auto-degrade left the system in.
                g_watchdogPassiveLocked.store(false, std::memory_order_relaxed);
                g_userModeLock.store(true, std::memory_order_relaxed);
                bool ok = transitionToState(SystemState::NORMAL, "user_set_mode_assist");
                if (!ok) {
                    LOG_WARN("set_mode=normal: transition to NORMAL blocked (state=%d), recording controlMode=assist intent",
                             (int)getSystemState());
                }
            } else if (mode == "emergency") {
                // ROUND-004: emergency is an internal/watchdog-only state. Users
                // (WebUI / root FIFO set_mode=) must NOT be able to force it; it is
                // entered only by the thermal/emergency latch via set_control_mode=.
                res.success = false;
                res.error_code = ERR_INVALID_ARGUMENT;
                res.message = "emergency is internal-only (watchdog/thermal latch), not user-settable";
                LOG_WARN("set_mode=emergency rejected: internal-only, keeping current mode");
            } else {
                std::string curMode;
                { std::lock_guard<std::mutex> cl(g_cfgMutex); curMode = g_cfg.controlMode; }
                res.success = false;
                res.error_code = ERR_INVALID_ARGUMENT;
                res.message = "invalid control mode (user-selectable: passive/assist/active)";
                LOG_WARN("Invalid set_mode value: '%s', keeping current: %s", mode.c_str(), curMode.c_str());
            }
            // P2-#13: ALWAYS update g_cfg.controlMode to the user-selected mode
            // (not just on transition failure). Before this fix, a successful
            // transition left g_cfg.controlMode stale, so placement.cpp's
            // controlMode=="passive" gate kept blocking migrations.
            // ROUND-005: preserve the user's exact mode. Previously both "active"
            // and "normal" were collapsed to "assist", which made WebUI unable
            // to highlight the aggressive mode (active) and broke the spillover
            // threshold matrix that reads g_cfg.controlMode verbatim.
            if (res.success) {
                std::string mappedMode;
                if (mode == "powersave" || mode == "passive") mappedMode = "passive";
                else if (mode == "assist") mappedMode = "assist";
                else if (mode == "active") mappedMode = "active";
                else if (mode == "normal") mappedMode = "assist";  // legacy alias
                if (!mappedMode.empty()) {
                    // ROUND-007: user set_mode sets BOTH the persisted user choice
                    // AND the effective mode. This also CLEARS any safety override
                    // (the user explicitly chose a mode, which wins over latch).
                    setUserControlMode(mappedMode);
                    bool inEmergency = (getSystemState() == SystemState::EMERGENCY);
                    std::lock_guard<std::mutex> cl(g_cfgMutex);
                    g_cfg.controlMode = mappedMode;
                    // P3-1 (lesson #20): if the user picked a mode WHILE the thermal
                    // emergency latch is active, remember that so the thermal recovery
                    // block keeps this choice instead of silently restoring the stale
                    // pre-emergency snapshot. g_cfg.controlMode already = mappedMode.
                    if (inEmergency) {
                        g_emergencyUserOverride.store(true, std::memory_order_relaxed);
                    }
                    // P2-4: keep control_mode_effective in lockstep with the user's
                    // explicit choice. transitionToState() only rewrites effective on
                    // an actual state CHANGE; a user switch while already NORMAL was a
                    // no-op transition, leaving effective stale at the old assist.
                    // Do NOT clobber it while EMERGENCY (the system-enforced safety
                    // override) is active — that path stays "emergency".
                    if (!inEmergency) {
                        atomicWriteFile(
                            (std::string(STATE_DIR) + "/control_mode_effective").c_str(),
                            mappedMode);
                    }
                }
            }
            std::string finalControlMode;
            { std::lock_guard<std::mutex> cl(g_cfgMutex); finalControlMode = g_cfg.controlMode; }
            atomicWriteFile((std::string(STATE_DIR) + "/control_mode").c_str(), finalControlMode);
            persistConfigKeyValue("CONTROL_MODE", finalControlMode.c_str());
            LOG_INFO("[CFG] control_mode=%s (persisted to aatpe.conf)", finalControlMode.c_str());
        }
        // P1-1: watchdog-initiated control-mode change via control pipe.
        // Format: set_control_mode=<mode>&reason=<reason>
        // This routes through setRuntimeControlMode() so that g_cfg.controlMode,
        // g_systemState, STATE_DIR/control_mode, and WebUI all stay consistent.
        else if (line.rfind("set_control_mode=", 0) == 0) {
            std::string payload = line.substr(17);  // after "set_control_mode="
            // Split on '&' to separate mode from reason.
            std::string mode, reason;
            size_t amp = payload.find('&');
            if (amp != std::string::npos) {
                mode = payload.substr(0, amp);
                std::string rest = payload.substr(amp + 1);
                // rest should be "reason=<reason_value>"
                if (rest.rfind("reason=", 0) == 0) {
                    reason = rest.substr(7);
                }
            } else {
                mode = payload;
            }
            trim(mode);
            trim(reason);
            bool ok = setRuntimeControlMode(mode, reason);
            if (ok) {
                res.success = true;
                res.applied_value = mode;
            } else {
                res.success = false;
                res.error_code = ERR_INVALID_ARGUMENT;
                res.message = "invalid control mode (must be active/assist/passive/emergency)";
            }
        }
        else if (line == "unlock_watchdog") {
        res.success = true;
            // Fix: manually unlock watchdog passive lock so PASSIVE -> NORMAL works
            // without daemon restart. This is the runtime unlock path that WebUI
            // and aatpe-cli use when the watchdog has locked the system into PASSIVE.
            bool wasLocked = isWatchdogPassiveLocked();
            g_watchdogPassiveLocked.store(false, std::memory_order_relaxed);
            LOG_WARN("WATCHDOG: manual unlock_watchdog command received, wasLocked=%d",
                     wasLocked ? 1 : 0);
            // If we are currently stuck in PASSIVE, attempt the PASSIVE -> NORMAL
            // transition now that the lock is cleared.
            if (getSystemState() == SystemState::PASSIVE) {
                bool ok = transitionToState(SystemState::NORMAL, "manual_unlock_watchdog");
                if (ok) {
                    LOG_WARN("WATCHDOG: PASSIVE -> NORMAL transitioned after manual unlock");
                } else {
                    LOG_WARN("WATCHDOG: still cannot leave PASSIVE after unlock "
                             "(priority/other block), current state=%d",
                             (int)getSystemState());
                }
            }
            // Write state file so WebUI reflects the cleared lock immediately.
            atomicWriteFile((std::string(STATE_DIR) + "/watchdog_passive_locked").c_str(),
                            "0");
        }
        else if (line.rfind("set_profile=", 0) == 0) {
        res.success = true;
            std::string prof = line.substr(12);
            trim(prof);
            // P2 Problem15: manual profile selection. Locking the profile and
            // forcing autoProfile=0 ensures neither the auto-profile layer nor the
            // thermal auto-switch (guarded by !g_thermalEmergency && !g_profileLock)
            // can override this. Only EMERGENCY can, and it restores on recovery.
            // P3-3: validate profile name instead of silently accepting anything
            if (prof == "balanced" || prof == "gaming" || prof == "battery" || prof == "thermal") {
                // manual pick votes MANUAL (2nd highest
                // priority, only EMERGENCY can override). The arbiter applies it.
                aatpe_profile::profileRequest(prof, aatpe_profile::ProfileSource::MANUAL);
                // Fix-E (P2): explicit relaxed store, aligned with sibling flags
                // g_watchdogPassiveLocked/g_userModeLock. g_profileLock is already
                // std::atomic<bool>; the implicit `=` store is atomic but seq_cst,
                // so make the relaxed ordering explicit and consistent.
                g_profileLock.store(true, std::memory_order_relaxed);
                // P1-11: immediately abstain the AUTO layer so the manual lock takes
                // effect on THIS cycle instead of waiting for the next autoSelectProfile()
                // tick (which would otherwise keep voting AUTO until the next loop).
                aatpe_profile::profileRelease(aatpe_profile::ProfileSource::AUTO);
                // protect direct g_cfg write (profileRequest already
                // released g_cfgMutex before returning).
                {
                    std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                    g_cfg.autoProfile = 0;
                }
                // profile_lock/auto_profile are durable control flags.
                atomicWriteFile((std::string(STATE_DIR) + "/profile_lock").c_str(), 1);
                atomicWriteFile((std::string(STATE_DIR) + "/auto_profile").c_str(), 0);
                // persist profile selection + auto_profile=0 to aatpe.conf
                persistConfigKeyValue("CURRENT_PROFILE", prof.c_str());
                persistConfigKeyValue("AUTO_PROFILE", "0");
            } else {
                res.success = false;
                LOG_WARN("Invalid set_profile value: '%s' (must be balanced/gaming/battery/thermal), keeping current: %s", prof.c_str(), aatpe_profile::effectiveProfile().c_str());
            }
        }
        else if (line.rfind("set_auto_profile=", 0) == 0) {
        res.success = true;
            const char* autoVal = line.c_str() + 17;
            if (!isAllDigits(autoVal)) {
                // snapshot autoProfile for the error log.
                int curAuto;
                { std::lock_guard<std::mutex> cl(g_cfgMutex); curAuto = g_cfg.autoProfile; }
                res.success = false;
                LOG_WARN("Invalid set_auto_profile value: '%s' (must be integer 0 or 1), keeping current: %d", autoVal, curAuto);
            } else {
                // R6-004: reject overflow instead of collapsing to 0 (which would
                // silently disable auto_profile / set the manual lock).
                int val = 0;
                if (!parseNonNegChecked(autoVal, val)) {
                    int curAuto;
                    { std::lock_guard<std::mutex> cl(g_cfgMutex); curAuto = g_cfg.autoProfile; }
                    res.success = false;
                    LOG_WARN("Invalid set_auto_profile value: '%s' (overflow / must be 0 or 1), keeping current: %d", autoVal, curAuto);
                } else if (val != 0 && val != 1) {
                    // P1 round7: strictly only 0/1 (was any nonzero treated as ON).
                    int curAuto;
                    { std::lock_guard<std::mutex> cl(g_cfgMutex); curAuto = g_cfg.autoProfile; }
                    res.success = false;
                    LOG_WARN("Invalid set_auto_profile value: '%s' (must be exactly 0 or 1), keeping current: %d", autoVal, curAuto);
                } else {
                    int writtenAuto;
                    {
                        std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                        g_cfg.autoProfile = (val != 0) ? 1 : 0;
                        writtenAuto = g_cfg.autoProfile;
                    }
                    g_profileLock.store((val == 0), std::memory_order_relaxed);
                    atomicWriteFile((std::string(STATE_DIR) + "/auto_profile").c_str(), writtenAuto);
                    atomicWriteFile((std::string(STATE_DIR) + "/profile_lock").c_str(),
                                    g_profileLock.load(std::memory_order_relaxed) ? 1 : 0);
                    // enabling auto releases the MANUAL lock so
                    // AUTO can drive; disabling auto abstains AUTO and falls back to
                    // MANUAL (if set) or GLOBAL.
                    if (writtenAuto) {
                        aatpe_profile::profileRelease(aatpe_profile::ProfileSource::MANUAL);
                    } else {
                        aatpe_profile::profileRelease(aatpe_profile::ProfileSource::AUTO);
                    }
                    // persist auto_profile to aatpe.conf
                    persistConfigKeyValue("AUTO_PROFILE", writtenAuto ? "1" : "0");
                }
            }
        }
        else if (line.rfind("set_log_level=", 0) == 0) {
        res.success = true;
            const char* logVal = line.c_str() + 14;
            if (!isAllDigits(logVal)) {
                res.success = false;
                // P3-16: range matches config LOG_LEVEL clamp [0,5] (was 0-4).
                LOG_WARN("Invalid set_log_level value: '%s' (must be integer 0-5), keeping current: %d", logVal, g_logLevel.load());
            } else {
                // R6-003: reject overflow — parseIntSafe used to collapse
                // "9999999999" -> 0, which then passed the [0,5] check as log=0.
                int lv = 0;
                if (!parseNonNegChecked(logVal, lv)) {
                    res.success = false;
                    LOG_WARN("Invalid set_log_level value: '%s' (overflow, must be 0-5), keeping current: %d", logVal, g_logLevel.load());
                } else if (lv >= 0 && lv <= 5) {
                    g_logLevel.store(lv);
                    // protect direct g_cfg write.
                    { std::lock_guard<std::mutex> cfgLock(g_cfgMutex); g_cfg.logLevel = lv; }
                    writeFile((std::string(STATE_DIR) + "/log_level").c_str(), g_logLevel.load());
                    persistConfigKeyValue("LOG_LEVEL", std::to_string(lv).c_str());
                } else {
                    res.success = false;
                    LOG_WARN("Invalid set_log_level value: %d (must be 0-5), keeping current: %d", lv, g_logLevel.load());
                }
            }
        }
        // v4.2.1: manual game-override list (game_overrides.list). The whitelist
        // already validated the package shape; re-validate defensively here.
        else if (line.rfind("game_add=", 0) == 0) {
            std::string pkg = line.substr(9);
            if (aatpe::gamelist::addManualGame(pkg)) {
                res.success = true;
                LOG_INFO("game_add: %s (manual override list updated)", pkg.c_str());
            } else {
                res.success = false;
                res.message = "invalid package name";
                LOG_WARN("game_add rejected: '%s'", pkg.c_str());
            }
        }
        else if (line.rfind("game_remove=", 0) == 0) {
            std::string pkg = line.substr(12);
            if (aatpe::gamelist::removeManualGame(pkg)) {
                res.success = true;
                LOG_INFO("game_remove: %s (manual override list updated)", pkg.c_str());
            } else {
                res.success = false;
                res.message = "invalid package name";
                LOG_WARN("game_remove rejected: '%s'", pkg.c_str());
            }
        }
        else if (line == "stop") {
            res.success = true;
            g_shouldExit.store(1, std::memory_order_relaxed);
        }
        else if (line == "restart") {
        res.success = true;
            // item 8: do NOT bypass the Profile Manager with a direct loadProfile().
            // loadConfig() already re-votes CURRENT_PROFILE as GLOBAL internally
            // (P1-5); this is an explicit re-arbitration so any on-disk .conf
            // edit is re-applied even if CURRENT_PROFILE itself did not change.
            loadConfig();
            aatpe_profile::profileReapplyWinner();
        }
        // ML model control commands
        else if (line.rfind("model_reset=", 0) == 0) {
        res.success = true;
            std::lock_guard<std::mutex> mlLock(g_mlMutex);
            g_mlModel.reset();
            unlink(mlModelPath());
            unlink((std::string(mlModelPath()) + ".bak").c_str());
            LOG_INFO("ML model reset via control command");
        }
        else if (line.rfind("model_save=", 0) == 0) {
        res.success = true;
            // v6.0.0 RT-A A4: hold g_mlMutex only for the model serialization
            // (g_mlModel.save). backupModelFile() (a full file copy) + stat used to
            // run under g_mlMutex, inconsistent with the periodic save path
            // (aatped_main.cpp releases the lock before backup). Do the file copy /
            // stat / state-file writes OUTSIDE the lock.
            const char* mp = mlModelPath();
            bool saved = false;
            int totalSamples = 0;
            {
                std::lock_guard<std::mutex> mlLock(g_mlMutex);
                saved = g_mlModel.save(mp);
                totalSamples = g_mlModel.getTotalSamples();
            }
            if (saved) {
                g_mlSaveSuccess++;
                backupModelFile(mp);
                struct stat st;
                long long fsize = -1;
                if (stat(mp, &st) == 0) fsize = (long long)st.st_size;
                LOG_INFO("ML model saved via control: path=%s bytes=%lld samples=%d",
                         mp, fsize, totalSamples);
                updateMlSaveStateFiles(true, mp);
            } else {
                g_mlSaveFail++;
                LOG_WARN("ML model save via control FAILED: path=%s errno=%d (%s)",
                         mp, errno, aatpeErrStr(errno));
                updateMlSaveStateFiles(false, mp);
            }
        }
        // v6.0.0: read-only shadow-ring export. Drains up to 512 oldest observe-
        // only samples and writes them as JSONL into the root-only diagnostic dir.
        // This performs NO control action (no mode change / no boost / no affinity);
        // it only telemetry-exports what the passive sampler already recorded.
        // Auth is identical to every other line through this executor: the control
        // pipe is root-0600 and HMAC-verified when a .sig= is present, so an
        // unauthenticated producer cannot reach it. Output is NEVER written to
        // /sdcard; it stays under STATE_DIR (mode 0700, root only).
        else if (line.rfind("shadow_dump=", 0) == 0) {
            res.success = true;
            std::string diagDir = std::string(STATE_DIR) + "/diagnostic";
            // The diagnostic dir is created 0700 at module install/init time.
            // mkdir() here is best-effort ONLY when the dir is missing (it does
            // NOT change permissions on an existing dir); the daemon's umask(0077)
            // guarantees a freshly-created one is 0700 anyway.
            ::mkdir(diagDir.c_str(), 0700);
            std::string outPath = diagDir + "/shadow_samples.jsonl";
            // v6.0.0 RT-A A3: hold g_mlMutex ONLY long enough to drain the ring
            // into an owned vector. The 512x snprintf + string append used to run
            // under g_mlMutex, lengthening ML-lock hold for webui model.json
            // readers; release the lock, THEN serialize + writeFileAtomic.
            std::vector<aatpe_ml::LearningModel::ShadowSampleView> samples;
            int drained = 0;
            {
                std::lock_guard<std::mutex> mlLock(g_mlMutex);
                samples = g_mlModel.drainShadowSamples(512, /*clear=*/true);
                drained = (int)samples.size();
            }
            std::string jsonl;
            jsonl.reserve(samples.size() * 256);
            char line[1024];
            for (const auto& s : samples) {
                // One JSON object per line. Fixed 14-feature schema; floats
                // printed with %.6g to stay deterministic and compact.
                snprintf(line, sizeof(line),
                    "{\"pool\":%d,\"outcome\":%.6g,"
                    "\"f\":[%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g,%.6g]}\n",
                    s.pool, s.outcome,
                    s.features.avg_run_us, s.features.nr_switches,
                    s.features.cpu_usage, s.features.priority,
                    s.features.nice, s.features.is_game,
                    s.features.thermal, s.features.capacity,
                    s.features.current_cpu_match, s.features.migration_count,
                    s.features.cross_run_cap, s.features.cross_run_usage,
                    s.features.cross_cap_thermal, s.features.cross_run_thermal);
                jsonl += line;
            }
            if (writeFileAtomic(outPath.c_str(), jsonl)) {
                LOG_INFO("shadow_dump: drained %d sample(s) -> %s", drained, outPath.c_str());
            } else {
                res.success = false;
                LOG_WARN("shadow_dump: atomic write FAILED: %s errno=%d (%s)",
                         outPath.c_str(), errno, aatpeErrStr(errno));
            }
        }
        // Hybrid learning dynamic toggle (experimental)
        else if (line.rfind("set_ml_hybrid=", 0) == 0) {
        res.success = true;
            const char* hybridVal = line.c_str() + 14;
            if (!isAllDigits(hybridVal)) {
                // snapshot for error log.
                int curHybrid;
                { std::lock_guard<std::mutex> cl(g_cfgMutex); curHybrid = g_cfg.mlHybridEnabled ? 1 : 0; }
                res.success = false;
                LOG_WARN("Invalid set_ml_hybrid value: '%s' (must be 0 or 1), keeping current: %d",
                         hybridVal, curHybrid);
            } else {
                // G2-003: reject overflow AND non 0/1 values. parseIntSafe used to
                // collapse a huge digit string to 0, which silently disabled the
                // feature instead of reporting an error.
                int val = 0;
                if (!parseNonNegChecked(hybridVal, val) || (val != 0 && val != 1)) {
                    // snapshot for error log.
                    int curHybrid;
                    { std::lock_guard<std::mutex> cl(g_cfgMutex); curHybrid = g_cfg.mlHybridEnabled ? 1 : 0; }
                    res.success = false;
                    LOG_WARN("Invalid set_ml_hybrid value: '%s' (must be 0 or 1), keeping current: %d",
                             hybridVal, curHybrid);
                } else {
                bool newState = (val != 0);
                // ATOMIC CONFIG TRANSACTION.
                // Old code took cfg→hybrid in THREE separate critical sections,
                // leaving a window where hybrid was enabled but g_cfg said disabled
                // (or vice versa). Now we hold g_cfgMutex while taking g_hybridMutex
                // (canonical order: cfg → hybrid), so g_cfg and the hybrid runtime
                // state update as a single atomic step.
                bool stateChanged;
                {
                    std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                    stateChanged = (newState != g_cfg.mlHybridEnabled);
                    g_cfg.mlHybridEnabled = newState;
                    // Hold g_cfgMutex while taking g_hybridMutex (correct order).
                    std::lock_guard<std::mutex> hlock(g_hybridMutex);
                    aatpe_ml_hybrid::instance().setEnabled(newState);
                    if (stateChanged) {
                        const char* mp = mlModelPath();
                        std::string hybridPath = std::string(mp) + ".hybrid";
                        aatpe_ml_hybrid::instance().save(hybridPath.c_str());
                    }
                }
                // State file + persist happen OUTSIDE the locks (persistConfigKeyValue
                // takes its own g_cfgMutex).
                writeFile((std::string(STATE_DIR) + "/ml_hybrid_enabled").c_str(), newState ? "1" : "0");
                // persist hybrid learning to aatpe.conf
                persistConfigKeyValue("ML_HYBRID_ENABLED", newState ? "1" : "0");
                LOG_INFO("[ML-HYBRID] dynamic toggle: %s (was %s)",
                         newState ? "ENABLED" : "DISABLED",
                         newState ? "enabled" : "disabled");
                }
            }
        }
        // ML学习开关动态切换 (WebUI按钮 → control命令 → 内存+state+持久化)
        // 配置项ML_LEARNING_ENABLED存在, 但之前WebUI无对应按钮, processControlCommands也无处理。
        else if (line.rfind("set_ml_learning=", 0) == 0) {
        res.success = true;
            const char* mlVal = line.c_str() + 16;
            if (!isAllDigits(mlVal)) {
                // snapshot for error log.
                int curMl;
                { std::lock_guard<std::mutex> cl(g_cfgMutex); curMl = g_cfg.mlLearningEnabled ? 1 : 0; }
                res.success = false;
                LOG_WARN("Invalid set_ml_learning value: '%s' (must be 0 or 1), keeping current: %d",
                         mlVal, curMl);
            } else {
                // G2-003: reject overflow AND non 0/1 values (parseIntSafe collapse
                // to 0 silently disabled learning).
                int val = 0;
                if (!parseNonNegChecked(mlVal, val) || (val != 0 && val != 1)) {
                    // snapshot for error log.
                    int curMl;
                    { std::lock_guard<std::mutex> cl(g_cfgMutex); curMl = g_cfg.mlLearningEnabled ? 1 : 0; }
                    res.success = false;
                    LOG_WARN("Invalid set_ml_learning value: '%s' (must be 0 or 1), keeping current: %d",
                             mlVal, curMl);
                } else {
                bool newState = (val != 0);
                // ATOMIC CONFIG TRANSACTION.
                // Old code wrote g_cfg.mlLearningEnabled under g_cfgMutex, released
                // the lock, then took g_mlMutex — leaving a window where g_cfg said
                // enabled but g_mlModel was still disabled. Now we hold g_cfgMutex
                // while taking g_mlMutex (canonical order: cfg → ml).
                bool stateChanged;
                {
                    std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                    stateChanged = (newState != g_cfg.mlLearningEnabled);
                    g_cfg.mlLearningEnabled = newState;
                    // Hold g_cfgMutex while taking g_mlMutex (correct order).
                    std::lock_guard<std::mutex> mlLock(g_mlMutex);
                    g_mlModel.setEnabled(newState);
                }
                // State file + persist OUTSIDE locks.
                writeFile((std::string(STATE_DIR) + "/ml_learning_enabled").c_str(),
                          newState ? "1" : "0");
                // 持久化到aatpe.conf
                persistConfigKeyValue("ML_LEARNING_ENABLED", newState ? "1" : "0");
                if (stateChanged) {
                    LOG_INFO("[ML-LEARNING] dynamic toggle: %s (was %s)",
                             newState ? "ENABLED" : "DISABLED",
                             newState ? "disabled" : "enabled");
                }
                }
            }
        }
        // Battery aging protection toggle (WebUI button sends battery_aging=0/1)
        else if (line.rfind("battery_aging=", 0) == 0) {
        res.success = true;
            const char* agingVal = line.c_str() + 14;
            if (!isAllDigits(agingVal)) {
                res.success = false;
                LOG_WARN("Invalid battery_aging value: '%s' (must be 0 or 1)", agingVal);
            } else {
                // G2-003: reject overflow AND non 0/1 values (parseIntSafe collapse
                // to 0 silently disabled battery aging protection).
                int val = 0;
                if (!parseNonNegChecked(agingVal, val) || (val != 0 && val != 1)) {
                    res.success = false;
                    LOG_WARN("Invalid battery_aging value: '%s' (must be 0 or 1)", agingVal);
                } else {
                // protect direct g_cfg write.
                {
                    std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                    g_cfg.batteryAgingProtection = (val != 0);
                }
                writeFile((std::string(STATE_DIR) + "/battery_aging_enabled").c_str(),
                          (val != 0) ? "1" : "0");
                // persist battery aging protection to aatpe.conf
                persistConfigKeyValue("BATTERY_AGING_PROTECTION", (val != 0) ? "1" : "0");
                LOG_INFO("[BATTERY-AGING] dynamic toggle: %s",
                         (val != 0) ? "ENABLED" : "DISABLED");
                }
            }
        }
        // ML cold start protection toggle via control command (replaces file-based toggle)
        else if (line.rfind("set_ml_cold_start=", 0) == 0) {
        res.success = true;
            const char* csVal = line.c_str() + 18;
            if (!isAllDigits(csVal)) {
                res.success = false;
                LOG_WARN("Invalid set_ml_cold_start value: '%s' (must be 0 or 1)", csVal);
            } else {
                // G2-003: reject overflow AND non 0/1 values (parseIntSafe collapse
                // to 0 silently disabled cold-start protection).
                int val = 0;
                if (!parseNonNegChecked(csVal, val) || (val != 0 && val != 1)) {
                    res.success = false;
                    LOG_WARN("Invalid set_ml_cold_start value: '%s' (must be 0 or 1)", csVal);
                } else {
                bool newState = (val != 0);
                // snapshot + write under g_cfgMutex.
                bool stateChanged;
                {
                    std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
                    stateChanged = (newState != g_cfg.mlColdStartProtection);
                    if (stateChanged) g_cfg.mlColdStartProtection = newState;
                }
                if (stateChanged) {
                    LOG_INFO("[ML-COLD-START] dynamic toggle: %s", newState ? "ENABLED" : "DISABLED");
                }
                writeFile((std::string(STATE_DIR) + "/ml_cold_start_enabled").c_str(), newState ? "1" : "0");
                // persist cold start protection to aatpe.conf
                persistConfigKeyValue("ML_COLD_START_PROTECTION", newState ? "1" : "0");
                }
            }
        }
        // WebUI explain target tid selection
        else if (line.rfind("explain_tid=", 0) == 0) {
        res.success = true;
            const char* tidVal = line.c_str() + 12;
            int tid = 0;
            if (!isAllDigits(tidVal)) {
                res.success = false;
                LOG_WARN("Invalid explain_tid value: '%s' (must be non-negative integer), setting to 0 (disabled)", tidVal);
                tid = 0;
            } else if (!parseNonNegChecked(tidVal, tid)) {
                // R6-020: isAllDigits() guarantees non-negativity, so the old
                // `if (tid < 0)` branch was dead. The real residual risk was
                // parseIntSafe collapsing an overflowing huge tid to 0 (=
                // "explain disabled"); reject overflow explicitly instead.
                res.success = false;
                LOG_WARN("Invalid explain_tid value: '%s' (overflow, must be non-negative integer)", tidVal);
            }
            if (res.success) {
                g_explainTid.store(tid);
                LOG_INFO("WebUI explain tid set to %d", tid);
            }
        }
        else if (line == "clear_log") {
        res.success = true;
            // D-20: Clear/truncate log via logging module
            logClear();
        }
        // reload_config — re-read aatpe.conf and re-apply current profile.
        else if (line == "reload_config") {
        res.success = true;
            // P1-5: loadConfig() itself parses CURRENT_PROFILE and re-votes it as
            // GLOBAL through the Profile Manager (never writes g_currentProfile
            // directly). We then force a re-apply of the winning profile so on-disk
            // tunable edits take effect even if the profile name did not change.
            std::string before = aatpe_profile::effectiveProfile();
            loadConfig();
            aatpe_profile::profileReapplyWinner();
            LOG_INFO("Control command: reload_config — config reloaded, GLOBAL re-voted, winner=%s",
                     aatpe_profile::effectiveProfile().c_str());
        }
        // runtime-tunable numeric config commands (persisted to aatpe.conf).
        // Each handler validates the value range, updates g_cfg under g_cfgMutex,
        // writes state files for WebUI readback, and persists to aatpe.conf.
        else if (line.rfind("set_decision_interval=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 22;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config DECISION_INTERVAL clamp [10,5000]
                // (was 50-2000).
                LOG_WARN("Invalid set_decision_interval: '%s' (must be integer 10-5000)", val);
            } else {
                // F03[P3]: parseNonNegChecked (consistent with other non-negative
                // tunables; rejects >10-digit overflow) instead of parseIntSafe.
                int ms = 0;
                if (!parseNonNegChecked(val, ms)) {
                    res.success = false;
                    LOG_WARN("Invalid set_decision_interval: '%s' (overflow, must be integer 10-5000)", val);
                } else if (ms >= 10 && ms <= 5000) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.decisionInterval = ms; }
                    writeFile((std::string(STATE_DIR) + "/decision_interval").c_str(), ms);
                    persistConfigKeyValue("DECISION_INTERVAL", std::to_string(ms).c_str());
                    LOG_INFO("[CFG] decision_interval=%d ms (persisted to aatpe.conf)", ms);
                } else {
                    res.success = false;
                    LOG_WARN("set_decision_interval=%d out of range (10-5000)", ms);
                }
            }
        }
        else if (line.rfind("set_confidence_threshold=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 25;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config CONFIDENCE_THRESHOLD clamp [0,100]
                // (was 1-100).
                LOG_WARN("Invalid set_confidence_threshold: '%s' (must be integer 0-100)", val);
            } else {
                // G2-002: reject overflow instead of letting parseIntSafe collapse a
                // 10-digit value to 0 (which then passes the 0<=t<=100 check and
                // silently writes 0). parseNonNegChecked returns false on overflow.
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_confidence_threshold: '%s' (overflow, must be integer 0-100)", val);
                } else if (t >= 0 && t <= 100) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.confidenceThreshold = t; }
                    writeFile((std::string(STATE_DIR) + "/confidence_threshold").c_str(), t);
                    persistConfigKeyValue("CONFIDENCE_THRESHOLD", std::to_string(t).c_str());
                    LOG_INFO("[CFG] confidence_threshold=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_confidence_threshold=%d out of range (0-100)", t);
                }
            }
        }
        else if (line.rfind("set_migration_cost_threshold=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 29;
            if (!isAllDigits(val)) {
                res.success = false;
                // P2-14: range matches the config clamp [0,10000] (was 1-100,
                // inconsistent with aatped_config.cpp MIGRATION_COST_THRESHOLD).
                LOG_WARN("Invalid set_migration_cost_threshold: '%s' (must be integer 0-10000)", val);
            } else {
                // G2-002: reject overflow (parseIntSafe used to collapse to 0, which
                // passed the 0<=t<=10000 check and silently wrote 0).
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_migration_cost_threshold: '%s' (overflow, must be integer 0-10000)", val);
                } else if (t >= 0 && t <= 10000) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.migrationCostThreshold = t; }
                    writeFile((std::string(STATE_DIR) + "/migration_cost_threshold").c_str(), t);
                    persistConfigKeyValue("MIGRATION_COST_THRESHOLD", std::to_string(t).c_str());
                    LOG_INFO("[CFG] migration_cost_threshold=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_migration_cost_threshold=%d out of range (0-10000)", t);
                }
            }
        }
        else if (line.rfind("set_max_migrations=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 19;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config MAX_MIGRATIONS_PER_SEC clamp
                // [1,1000] (was 1-500).
                LOG_WARN("Invalid set_max_migrations: '%s' (must be integer 1-1000)", val);
            } else {
                // F03[P3]: parseNonNegChecked (consistent; rejects overflow).
                int n = 0;
                if (!parseNonNegChecked(val, n)) {
                    res.success = false;
                    LOG_WARN("Invalid set_max_migrations: '%s' (overflow, must be integer 1-1000)", val);
                } else if (n >= 1 && n <= 1000) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.maxMigrationsPerSec = n; }
                    writeFile((std::string(STATE_DIR) + "/max_migrations_per_sec").c_str(), n);
                    persistConfigKeyValue("MAX_MIGRATIONS_PER_SEC", std::to_string(n).c_str());
                    LOG_INFO("[CFG] max_migrations_per_sec=%d (persisted to aatpe.conf)", n);
                } else {
                    res.success = false;
                    LOG_WARN("set_max_migrations=%d out of range (1-1000)", n);
                }
            }
        }
        else if (line.rfind("set_thermal_enabled=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 20;
            if (!isAllDigits(val)) {
                res.success = false;
                LOG_WARN("Invalid set_thermal_enabled: '%s' (must be 0 or 1)", val);
            } else if (strcmp(val, "0") != 0 && strcmp(val, "1") != 0) {
                // P3-2: strict on/off — reject 2/10/01 etc. (no arbitrary non-zero = on).
                res.success = false;
                LOG_WARN("Invalid set_thermal_enabled: '%s' (only 0=off, 1=on accepted)", val);
            } else {
                bool en = (val[0] == '1');
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.thermalEnabled = en; }
                    writeFile((std::string(STATE_DIR) + "/thermal_enabled").c_str(), en ? "1" : "0");
                    persistConfigKeyValue("THERMAL_ENABLED", en ? "1" : "0");
                    LOG_INFO("[CFG] thermal_enabled=%d (persisted to aatpe.conf)", en ? 1 : 0);
            }
        }
        // ---- v6.0.0 round4c: user-tunable feature switches ----
        else if (line.rfind("set_c4_freezer=", 0) == 0) {
            res.success = true;
            const char* val = line.c_str() + 15;
            if (!isAllDigits(val)) {
                res.success = false;
                LOG_WARN("Invalid set_c4_freezer: '%s' (must be 0 or 1)", val);
            } else if (strcmp(val, "0") != 0 && strcmp(val, "1") != 0) {
                res.success = false;
                LOG_WARN("Invalid set_c4_freezer: '%s' (only 0=off, 1=on accepted)", val);
            } else {
                bool en = (val[0] == '1');
                { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.c4FreezerEnabled = en; }
                aatpe::c4freezer::setC4FreezerEnabled(en);
                writeFile((std::string(STATE_DIR) + "/c4_freezer_enabled").c_str(), en ? "1" : "0");
                persistConfigKeyValue("C4_FREEZER_ENABLED", en ? "1" : "0");
                LOG_INFO("[CFG] c4_freezer_enabled=%d", en ? 1 : 0);
            }
        }
        else if (line.rfind("set_ebpf=", 0) == 0) {
            res.success = true;
            const char* val = line.c_str() + 9;
            if (!isAllDigits(val)) {
                res.success = false;
                LOG_WARN("Invalid set_ebpf: '%s' (must be 0 or 1)", val);
            } else if (strcmp(val, "0") != 0 && strcmp(val, "1") != 0) {
                res.success = false;
                LOG_WARN("Invalid set_ebpf: '%s' (only 0=off, 1=on accepted)", val);
            } else {
                bool en = (val[0] == '1');
                { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.ebpfEnabled = en; }
                writeFile((std::string(STATE_DIR) + "/ebpf_event_driven").c_str(), en ? "1" : "0");
                // CFG-39: loadConfig accepts BOTH EBPF_EVENT_DRIVEN (line ~841) and
                // EBPF_ENABLED (line ~969) and both write g_cfg.ebpfEnabled, with
                // the later parse winning. Historically this command only wrote
                // EBPF_EVENT_DRIVEN, leaving a legacy EBPF_ENABLED=1 line untouched
                // in the conf; on the next hot-reload the EBPF_ENABLED branch ran
                // AFTER and silently flipped the user's 0 back to 1. Persist BOTH
                // keys to the same value so they can never diverge.
                const char* vstr = en ? "1" : "0";
                persistConfigKeyValue("EBPF_EVENT_DRIVEN", vstr);
                persistConfigKeyValue("EBPF_ENABLED", vstr);
                LOG_INFO("[CFG] ebpf_event_driven=%d (auto-detect/auto-downgrade still enforced; both EBPF_* keys synced)", en ? 1 : 0);
            }
        }
        else if (line.rfind("set_federated=", 0) == 0) {
            res.success = true;
            const char* val = line.c_str() + 14;
            if (!isAllDigits(val)) {
                res.success = false;
                LOG_WARN("Invalid set_federated: '%s' (must be 0 or 1)", val);
            } else if (strcmp(val, "0") != 0 && strcmp(val, "1") != 0) {
                res.success = false;
                LOG_WARN("Invalid set_federated: '%s' (only 0=off, 1=on accepted)", val);
            } else {
                bool en = (val[0] == '1');
                { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.federatedEnabled = en; }
                writeFile((std::string(STATE_DIR) + "/federated_enabled").c_str(), en ? "1" : "0");
                persistConfigKeyValue("FEDERATED_ENABLED", en ? "1" : "0");
                LOG_INFO("[CFG] federated_enabled=%d (local export/import gated by this flag)", en ? 1 : 0);
            }
        }
        else if (line.rfind("set_thermal_limit_cpu=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 22;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config THERMAL_LIMIT_CPU clamp [0,200]
                // (was 40-150).
                LOG_WARN("Invalid set_thermal_limit_cpu: '%s' (must be integer 0-200)", val);
            } else {
                // G2-002: reject overflow. parseIntSafe used to collapse a huge
                // value to 0, which then passed 0<=t<=200 and wrote thermalLimitCpu=0
                // -> CPU permanently over-throttled. parseNonNegChecked rejects it.
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_thermal_limit_cpu: '%s' (overflow, must be integer 0-200)", val);
                } else if (t >= 0 && t <= 200) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.thermalLimitCpu = t; }
                    writeFile((std::string(STATE_DIR) + "/thermal_limit_cpu").c_str(), t);
                    persistConfigKeyValue("THERMAL_LIMIT_CPU", std::to_string(t).c_str());
                    LOG_INFO("[CFG] thermal_limit_cpu=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_thermal_limit_cpu=%d out of range (0-200)", t);
                }
            }
        }
        else if (line.rfind("set_thermal_limit_skin=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 23;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config THERMAL_LIMIT_SKIN clamp [0,200]
                // (was 30-60).
                LOG_WARN("Invalid set_thermal_limit_skin: '%s' (must be integer 0-200)", val);
            } else {
                // G2-002: reject overflow (parseIntSafe collapse-to-0 would write 0).
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_thermal_limit_skin: '%s' (overflow, must be integer 0-200)", val);
                } else if (t >= 0 && t <= 200) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.thermalLimitSkin = t; }
                    writeFile((std::string(STATE_DIR) + "/thermal_limit_skin").c_str(), t);
                    persistConfigKeyValue("THERMAL_LIMIT_SKIN", std::to_string(t).c_str());
                    LOG_INFO("[CFG] thermal_limit_skin=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_thermal_limit_skin=%d out of range (0-200)", t);
                }
            }
        }
        else if (line.rfind("set_thermal_limit_battery=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 26;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config THERMAL_LIMIT_BATTERY clamp [0,200]
                // (was 30-70).
                LOG_WARN("Invalid set_thermal_limit_battery: '%s' (must be integer 0-200)", val);
            } else {
                // G2-002: reject overflow (parseIntSafe collapse-to-0 would write 0).
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_thermal_limit_battery: '%s' (overflow, must be integer 0-200)", val);
                } else if (t >= 0 && t <= 200) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.thermalLimitBattery = t; }
                    writeFile((std::string(STATE_DIR) + "/thermal_limit_battery").c_str(), t);
                    persistConfigKeyValue("THERMAL_LIMIT_BATTERY", std::to_string(t).c_str());
                    LOG_INFO("[CFG] thermal_limit_battery=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_thermal_limit_battery=%d out of range (0-200)", t);
                }
            }
        }
        else if (line.rfind("set_thermal_emergency=", 0) == 0) {
        res.success = true;
            const char* val = line.c_str() + 22;
            if (!isAllDigits(val)) {
                res.success = false;
                // P3-16: range matches config THERMAL_EMERGENCY clamp [0,200]
                // (was 60-150). The compiled-in production default remains 120;
                // this only widens the accepted command range to match the config.
                LOG_WARN("Invalid set_thermal_emergency: '%s' (must be integer 0-200)", val);
            } else {
                // G2-002: reject overflow (parseIntSafe collapse-to-0 would write 0,
                // meaning emergency trips immediately).
                int t = 0;
                if (!parseNonNegChecked(val, t)) {
                    res.success = false;
                    LOG_WARN("Invalid set_thermal_emergency: '%s' (overflow, must be integer 0-200)", val);
                } else if (t >= 0 && t <= 200) {
                    { std::lock_guard<std::mutex> lk(g_cfgMutex); g_cfg.thermalEmergency = t; }
                    // THM-04: do NOT write the threshold to the live thermal_emergency
                    // flag file. That file holds "1"/"0" (emergency ACTIVE), owned
                    // exclusively by thermal.cpp / transitionToState. Writing the
                    // threshold there corrupted the live flag (CLI printed
                    // "Emergency: 95" and the watchdog read a non-1 value).
                    // The new threshold persists to aatpe.conf below.
                    persistConfigKeyValue("THERMAL_EMERGENCY", std::to_string(t).c_str());
                    LOG_INFO("[CFG] thermal_emergency=%d (persisted to aatpe.conf)", t);
                } else {
                    res.success = false;
                    LOG_WARN("set_thermal_emergency=%d out of range (0-200)", t);
                }
            }
        }
        // P3-5: warn on unknown control commands so typos are discovered.
        // P3-31: set the unified error code/message HERE (the old post-loop
        // `if (!recognized)` block was redundant with this else branch).
        else {
            res.success = false;
            res.error_code = aatpe::ERR_UNKNOWN_COMMAND;
            res.message = "no matching command";
            LOG_WARN("Unknown control command: '%s' (ignored)", line.c_str());
        }
        // R6-017: the redundant `(void)recognized;` is gone — recognized is set by
        // every branch and the else above already encodes the unknown-command
        // result into res.
        return res;
}

// ============================================================================
// DAEMON INIT & LOOP
// ============================================================================
// ============================================================================
// APK Smart Detection
// Detects whether the AATPE-Helper APK (com.aatpe.helper) is installed.
// If installed, auto_profile is forced off so the APK controls profile switching.
// Uses aatpeExec with built-in 3s total timeout to avoid daemon startup hangs.
// Safe fallback: any failure (timeout, exec error, empty output) returns false.
// ============================================================================
static bool isHelperApkInstalled() {
    // R6-018: applyHelperApkDetection() runs every 30s and this previously fork+exec'd
    // `pm list packages` each time (a shell+pm invocation per tick). APK
    // install/uninstall is rare, so cache the result and only re-exec once per
    // kProbeIntervalSec; a missed install for up to that TTL is harmless for
    // auto-profile suppression.
    static constexpr long long kProbeIntervalMs = 60LL * 1000LL;
    static std::mutex s_cacheMutex;
    static long long s_lastProbeMs = 0;
    static bool s_cachedInstalled = false;
    long long nowMs = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
    {
        std::lock_guard<std::mutex> lk(s_cacheMutex);
        if (nowMs - s_lastProbeMs < kProbeIntervalMs) return s_cachedInstalled;
        s_lastProbeMs = nowMs;
    }
    // 精确查询特定包名，避免全量扫描 + 子串误匹配
    std::string out = aatpeExec("pm list packages com.aatpe.helper 2>/dev/null", "HELPER_APK");
    bool installed = false;
    if (!out.empty()) {
        std::string lower = out;
        std::transform(lower.begin(), lower.end(), lower.begin(),
                       [](unsigned char c) { return std::tolower(c); });
        installed = lower.find("package:com.aatpe.helper") != std::string::npos;
    }
    {
        std::lock_guard<std::mutex> lk(s_cacheMutex);
        s_cachedInstalled = installed;
    }
    return installed;
}

// Apply APK detection result to auto_profile state.
// Called after loadConfig() in daemonInit and every 30s in the main loop.
// do NOT overwrite the user's configured AUTO_PROFILE
// (g_cfg.autoProfile). We only set a runtime suppression flag
// g_helperAutoSuppressed. The effective decision is
//   effectiveAuto = g_cfg.autoProfile && !g_helperAutoSuppressed.
// When the Helper APK is removed, the flag clears and the user's original
// AUTO_PROFILE resumes — we never mutated their config.
void applyHelperApkDetection() {
    // P1-4: snapshot g_cfg.autoProfile under g_cfgMutex — it is written by the
    // config-hot-reload thread and the set_profile command path; reading it
    // unlocked here was a data race.
    int cfgAutoProfile;
    {
        std::lock_guard<std::mutex> cfgLock(g_cfgMutex);
        cfgAutoProfile = g_cfg.autoProfile;
    }
    g_helperApkInstalled.store(isHelperApkInstalled());
    // C-011: protect g_autoProfileMode with g_autoProfileMutex.
    {
        std::lock_guard<std::mutex> apmLock(g_autoProfileMutex);
        if (g_helperApkInstalled) {
            g_helperAutoSuppressed.store(true);
            g_autoProfileMode = "apk_controlled";
        } else {
            g_helperAutoSuppressed.store(false);
            g_autoProfileMode = "module_controlled";
        }
    }
    if (g_helperApkInstalled) {
        LOG_INFO("Helper APK detected: auto_profile runtime-suppressed (APK controls switching; "
                 "user config AUTO_PROFILE=%d preserved)", cfgAutoProfile);
    } else {
        LOG_INFO("Helper APK not found: auto_profile %s (module controls switching)",
                 cfgAutoProfile ? "enabled" : "disabled");
    }
    writeFile((std::string(STATE_DIR) + "/helper_apk_installed").c_str(), g_helperApkInstalled.load() ? 1 : 0);
    std::string apmSnapshot;
    {
        std::lock_guard<std::mutex> apmLock(g_autoProfileMutex);
        apmSnapshot = g_autoProfileMode;
    }
    writeFile((std::string(STATE_DIR) + "/auto_profile_mode").c_str(), apmSnapshot);
    int effectiveAuto = cfgAutoProfile && !g_helperAutoSuppressed.load();
    atomicWriteFile((std::string(STATE_DIR) + "/auto_profile").c_str(), effectiveAuto);
}

